RDLogger.DisableLog('rdApp.*')
r=pathlib.Path(_ws + '/outputs/patbench-v1.0-20261030-r6');a=pathlib.Path(_ws + '/outputs/nitrile-evidence-audit-20261031');o=r/'structure_repair/nitrile_audit';o.mkdir(exist_ok=True)
