pending={'US08263781-20120911/US08263781-20120911-C00230.MOL':'原图碳端连接；例107名称与合成原料写isocyano，证据冲突，不能任选一种。','US08399681-20130319/US08399681-20130319-C00229.MOL':'关联专利例107重复相同图文冲突。','US11285151-20220329/US11285151-20220329-C00101.MOL':'MSX-178；原图NC处于苯环右侧，连接方向有歧义，无明确系统名称或合成证据裁决。'}
m['decision']=np.where(m.structure_file.isin(pending),'holdout_unresolved','supported_nitrile')
