m['image_visually_reviewed']=m.test_tasks.ne('')|m.exact_superatom_labels.isin(['','CN','^NC'])|(m.exact_superatom_labels.eq('NC')&m.external_dx.le(.15))|m.structure_file.isin(pending)
m['review_note']=m.structure_file.map(pending).fillna('')
m=m.merge(inv[['structure_file','archive','smiles_before','smiles_after','rule']],on='structure_file',validate='many_to_one').merge(ctx,on='structure_file',validate='many_to_one')
m.to_parquet(o/'motif_decisions.parquet',index=False)
rec=inv.copy();ds=m.groupby('structure_file').decision.agg(lambda v:'holdout_unresolved' if 'holdout_unresolved' in set(v) else 'supported_nitrile');rec['decision']=rec.structure_file.map(ds);rec['review_note']=rec.structure_file.map(pending).fillna('');rec['image_visually_reviewed']=rec.structure_file.isin(m[m.image_visually_reviewed].structure_file);rec['n_motifs']=rec.structure_file.map(m.groupby('structure_file').size());rec['mol_sha256']=rec.structure_file.map(m.groupby('structure_file').mol_sha256.first());rec['image_sha256']=rec.structure_file.map(m.groupby('structure_file').image_sha256.first());rec['expected_after_inchikey']=rec.smiles_after.map(lambda s:Chem.MolToInchiKey(Chem.MolFromSmiles(s)));rec['before_smiles_sha256']=rec.smiles_before.map(lambda s:hashlib.sha256(s.encode()).hexdigest());rec.to_parquet(o/'record_decisions.parquet',index=False)
s=pd.read_parquet(r/'sar_all.parquet');isnit=s.structure_repair.fillna('').str.contains('nitrile');hold=s.structure_file.isin(pending)
rows=s.loc[isnit,['source_record_id','patent_core','group_id','structure_file','SMILES_before_repair','SMILES_as_drawn','split_time']].copy();rows['nitrile_audit_status']=rows.structure_file.map(ds);rows['nitrile_audit_holdout']=rows.structure_file.isin(pending);rows['nitrile_audit_reason']=rows.structure_file.map(pending).fillna('');rows.to_parquet(o/'row_decisions.parquet',index=False)
s['nitrile_audit_status']=s.structure_file.map(ds).fillna('not_applicable');s['nitrile_audit_holdout']=hold;s['nitrile_audit_reason']=s.structure_file.map(pending).fillna('')
# Derived table enforces quarantine using the existing build exclusion flag, with provenance in a separate column.
s['structure_alias_suspect_before_nitrile_audit']=s.structure_alias_suspect;s['structure_alias_suspect']=s.structure_alias_suspect|hold
s.to_parquet(o/'sar_all_reviewed.parquet',index=False)
quar=s[hold].copy();quar.to_parquet(o/'quarantined_records.parquet',index=False)
assert len(quar)==3 and rows.nitrile_audit_status.notna().all()
for f in (r/'tasks').glob('*.parquet'):
 d=pd.read_parquet(f);assert not d.source_record_id.str.contains('|'.join(quar.source_record_id),regex=True).any(),f
# retain source evidence for exceptions and all test files, without modifying source bytes
needed=set(m[m.image_visually_reviewed].image_file)
for fname in needed:
 p=o/'original_images'/fname;p.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(a/'originals'/fname,p)
# compact single-file visual review for all test files and quarantines
show=rec[rec.test_tasks.ne('')|rec.structure_file.isin(pending)].copy();items=[]
for t in show.itertuples():
 fname=t.structure_file[:-4]+'.TIF';im=Image.open(a/'originals'/fname);buf=io.BytesIO();im.save(buf,format='PNG',optimize=True)
 items.append({'patent':t.Patent,'compound':str(t.compound_alias),'file':t.structure_file,'test_tasks':t.test_tasks,'decision':t.decision,'note':t.review_note,'before':t.smiles_before,'after':t.smiles_after,'image':'data:image/png;base64,'+base64.b64encode(buf.getvalue()).decode(),'motifs':int(t.n_motifs),'image_sha256':t.image_sha256})
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PatBench 异腈转腈原图核查</title><style>body{font:16px system-ui;background:#f4f6fa;color:#1f2937;max-width:1160px;margin:24px auto;padding:0 16px}header{background:white;padding:22px;border-radius:12px}input,select,button{padding:10px;margin:5px;border:1px solid #aaa;border-radius:5px}article{background:white;padding:20px;margin:18px 0;border-radius:12px;border-left:5px solid #16806a}article.holdout_unresolved{border-color:#bd4a27}img{display:block;max-width:100%;max-height:520px;object-fit:contain;margin:15px auto}code{display:block;overflow-wrap:anywhere;font-size:13px;margin:10px 0}small{color:#586477}h1{font-size:25px}h2{font-size:19px}details{margin:14px 0}.sticky{position:sticky;top:0;background:#f4f6fa;padding:8px 0}#pages{margin:15px 0}</style><header><h1>PatBench：异腈转腈原图核查</h1><p>测试集556张原图（561处转换）已逐图核查，未发现此转换误改；另3条全量记录存在图文冲突或歧义，已隔离。下列展示556条测试记录和3条待定记录。原图来自原始USPTO压缩包，与原MOL按文件编号对应。</p><p>本页的“支持修复”只涉及异腈/腈的连接方式，不代表整条专利、分子其他基团或靶点已全部人工核准。全量7773个文件/7938处转换的证据等级见record_decisions与motif_decisions。</p></header><div class="sticky"><input id="query" placeholder="专利号、化合物编号、文件名"><select id="filter"><option value="all">全部</option><option value="holdout_unresolved">仅待定隔离（3）</option><option value="supported_nitrile">测试原图支持修复（556）</option></select><span id="count"></span><div id="pages"></div></div><main id="list"></main><script>const DATA=__DATA__;let page=0;const SIZE=12;const el=id=>document.getElementById(id);function node(tag,text){let n=document.createElement(tag);n.textContent=text;return n}function render(){let q=el('query').value.toLowerCase(),f=el('filter').value;let rows=DATA.filter(r=>(f==='all'||r.decision===f)&&[r.patent,r.compound,r.file,r.note].join(' ').toLowerCase().includes(q));page=Math.max(0,Math.min(page,Math.ceil(rows.length/SIZE)-1));el('count').textContent=` ${rows.length} 条`;el('list').replaceChildren();for(let r of rows.slice(page*SIZE,(page+1)*SIZE)){let a=document.createElement('article');a.className=r.decision;a.append(node('h2',`${r.patent} · ${r.compound}`),node('p',r.decision==='holdout_unresolved'?'待定，排除':'原图支持氰基修复'),node('small',r.file),node('p',r.note||r.test_tasks));let img=document.createElement('img');img.src=r.image;img.alt='原始专利结构图';img.loading='lazy';a.append(img);let d=document.createElement('details');d.append(node('summary','查看转换前后SMILES及证据哈希'));d.append(node('p','转换前：'),node('code',r.before),node('p','r6当前：'),node('code',r.after),node('small','原始TIF SHA256: '+r.image_sha256));a.append(d);el('list').append(a)}el('pages').replaceChildren();for(let [t,delta]of[['上一页',-1],['下一页',1]]){let b=node('button',t);b.onclick=()=>{page+=delta;render();window.scrollTo(0,0)};el('pages').append(b)}el('pages').append(node('span',`第 ${page+1}/${Math.max(1,Math.ceil(rows.length/SIZE))} 页`))}for(let id of['query','filter'])el(id).oninput=()=>{page=0;render()};render();</script></html>'''
(o/'nitrile_review.html').write_text(html.replace('__DATA__',json.dumps(items,ensure_ascii=False).replace('<','\\u003c')),encoding='utf8')
summary={'records':len(rec),'motifs':len(m),'patents':rec.Patent.nunique(),'sar_rows':int(isnit.sum()),'test_files':int(rec.test_tasks.ne('').sum()),'test_motifs':int(m.test_tasks.ne('').sum()),'test_patents':rec[rec.test_tasks.ne('')].Patent.nunique(),'quarantined_records':len(quar),'supported_records':int((rec.decision=='supported_nitrile').sum()),'image_visually_reviewed_files':int(rec.image_visually_reviewed.sum()),'image_visually_reviewed_motifs':int(m.image_visually_reviewed.sum()),'task_rows_affected_by_quarantine':0,'molecular_values_changed_by_this_audit':0,'structure_alias_suspect_before':int(s.structure_alias_suspect_before_nitrile_audit.sum()),'structure_alias_suspect_after':int(s.structure_alias_suspect.sum())}
